export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));export const nav=a=>`<nav>${[['dashboard','⌂','Dashboard'],['log','＋','Log'],['progress','↗','Progress'],['analytics','◒','Analytics'],['profile','●','Profile']].map(([r,i,l])=>`<a href="#/${r}" class="${a===r?'active':''}"><b>${i}</b><small>${l}</small></a>`).join('')}</nav>`;export const header=t=>`<header><a class="back" href="#/dashboard">‹</a><h1>${t}</h1><span></span></header>`;export const toast=m=>{let x=document.querySelector('.toast');if(!x){x=document.createElement('div');x.className='toast';document.body.append(x)}x.textContent=m;clearTimeout(window.__toast);window.__toast=setTimeout(()=>x.remove(),1800)};
